-- Gathering 2, generated by scripts/gen-gathering-sql.ts. Do not edit by hand.
insert into public.gathering_scripts (series_id, season_number, week, data) values
('dark-moon', 1, 2, '{"meta":{"dc":9,"ueDc":7,"def":24,"atk":17,"reward":520,"enemy":"The Robed","condition":"The chant: while more than half of them are standing, each has DEF +1.","ueAttr":"Intellect","ueTitle":"THE BREACH","barWay":"The Tunnel","barRisk":"The Room"},"steps":[{"t":"tonight","text":"Tonight: the Gathering. The old shaft goes down to a room older than the mill, and they are digging toward it. Tonight calls on Intellect.","section":""},{"t":"section","title":"Arrival","section":"Arrival"},{"t":"say","text":"The map was right. Deeper in the hill than the working chamber where they drove you back, down a shaft of its own and a stair cut so long ago its edges have worn soft as soap, there''s a second room — older than the one above it, older than the mill, older than anyone''s memory of this valley.\n\nYou hear the chanting before you see the light. Low, even, patient — the same few words, over and over, too muffled to make out. Not the sound of people in a hurry. The sound of people who have done this many times before.","section":"Arrival"},{"t":"section","title":"The Approach","section":"The Approach"},{"t":"pick","vote":true,"question":"HOW DO YOU GO DOWN?","options":[{"label":"NOW, UNDER THE CHANT","desc":"the chanting swallows the scrape of your boots."},{"label":"WAIT, AND COUNT","desc":"hold at the stair''s turn until you can set every voice in its place."}],"section":"The Approach","mode":"vote"},{"t":"say","text":"Either way there is still the stair, worn soft as soap, with no rail and a long drop on the open side.","section":"The Approach"},{"t":"approach","title":"THE SOFT STAIR","ways":[{"by":"Going now","attr":"Agility","verb":"take the stair without a slip"},{"by":"Having waited","attr":"Aim","verb":"mark each tread by the lamplight from below, and call the footing"}],"reward":"+500g · **and the party strikes first**","fail":"a boot goes out from under someone, and **they strike first**","section":"The Approach"},{"t":"say","text":"You reach the last step together, steady, blades already out.","cond":{"on":"approach","pass":true},"section":"The Approach"},{"t":"say","text":"You arrive in a clatter of steel on stone.","cond":{"on":"approach","pass":false},"section":"The Approach"},{"t":"section","title":"The Battle","section":"The Battle"},{"t":"say","text":"You come off the last step into lamplight.\n\n{N} robed figures stand in a ring around a stone table, lamps at their feet, their shadows thrown huge and wavering up the walls. On the table lies the miller''s boy — awake, wrists bound, his eyes finding yours over the shoulder of the one holding the knife.\n\nNobody shouts. The robed figures simply turn, all at once, as if they''d been expecting you. The chant doesn''t even break.","section":"The Battle"},{"t":"battle","name":"THE ROBED","firstLines":["You strike first.","He strikes first."],"desc":"**The chant:** while more than half of them are still standing, the chant holds, and each of them is harder to put down.","section":"The Battle"},{"t":"say","text":"It''s close and ugly — lamps kicked over, shadows lurching across the ceiling. And the strangest part is the chanting. The ones still standing keep the words going as they fight, and some keep them going as they fall, as if the words matter more than their lives.\n\nWhen the last of them goes down, the room goes enormously quiet.\n\nThe boy is alive. There''s a cut across his palm, clean and shallow, already bound in white linen — someone took the time to bind it. Whatever they needed from him, they''d already taken. The wound is small. The relief in the room is real. It looks, to everyone standing in it, like a win.","section":"The Battle"},{"t":"say","text":"Garrick reaches him first, kneeling, checking the bandage with careful hands, the same relief on his face as on everyone''s: *\"You saved that boy. Whatever else happened here, you saved him.\"*","section":"The Battle"},{"t":"say","text":"When the boy can talk again he does not tell you his name. You have had it all week. He asks for yours.","section":"The Battle"},{"t":"act","label":"TELL HIM YOUR NAME","section":"The Battle"},{"t":"say","text":"He says every name back under his breath, to keep it. Garrick''s is last. *\"Garrick,\"* he says, and the boy says it back, twice.","section":"The Battle"},{"t":"say","text":"Behind the stone table, at chest height: another socket, cut with the same deliberate care — empty. The dust at its rim is barely disturbed. Whatever sat here left recently, not centuries ago.","section":"The Battle"},{"t":"say","text":"The rubbing, laid against it, fits, the way the first one did.","section":"The Battle"},{"t":"section","title":"Notice","section":"Notice"},{"t":"notice","lines":{"Might":"The one you fought never once stepped away from the table. He was not defending himself. He was defending the place.","Agility":"There is a hole broken through the far wall, the rubble still sharp. They did not come down by your stair.","Intellect":"The knife has been wiped, and laid square to the table''s edge. Nobody in this room was in a hurry.","Charm":"Corin watches every face. The one thing he will not look at is the wall behind the table.","Craft":"The linen on his hand is tied with a knot you have seen before. On Tamsin''s.","Aim":"Beside the table, half trodden underfoot: a small book bound in black cloth, one corner smoking against a fallen lamp.","floor":"Down here the chant is still going. One of them, face down an arm''s length from you, is mouthing it into the stone."},"section":"Notice"},{"t":"act","label":"LOOK CLOSER","section":"Notice"},{"t":"lookCloser","lines":{"Might":"Even falling, he fell toward it.","Agility":"The pick marks are a day old at most. They broke through just ahead of you.","Intellect":"And there is very little blood. A cut that shallow was all they wanted.","Charm":"When the lamplight swings that way, he shuts his eyes.","Craft":"It is not a knot anybody ties in haste.","Aim":"It has fallen open. On its first page: a black circle."},"section":"Notice"},{"t":"section","title":"The black circle","section":"The black circle"},{"t":"say","text":"Beside the table, dropped in the fight and half trodden underfoot, lies a small book bound in black cloth, one corner scorched where it fell against a lamp.","section":"The black circle"},{"t":"say","text":"This belongs to *them*: their scripture, the kind of thing a man carries against his chest. On its first page, under a black circle painted like a moon with no light in it, is a title: *The First Book of the Order of the Dark Moon.*\n\nThe scrap of cloth torn from the scout''s coat, two nights ago on the hillside, lies beside it. The same circle.\n\nThe kidnappers have a name. And the Order''s scripture is about to tell you who they pray to.","section":"The black circle"},{"t":"section","title":"The United Effort","section":"The United Effort"},{"t":"say","text":"You have the black book in your hands when the far wall begins to sound.\n\nIt comes from the hole they dug: boots, a great many, and lamplight growing in it like water rising in a pipe. They left with what they came for. Now they are coming back for what they left behind: their dead, and their book.\n\nThere are more lamps in that tunnel than you can count. This is not a fight.\n\nBut they cut that tunnel in a night and a day, through ground nobody had disturbed in a thousand years, and it is standing on green timber and hope. Take out the right prop, and the hill will shut it for you. Take out the wrong one, and the fall comes down on your side of it.\n\nEvery fall changes what is holding what. So one of you looks, and calls it, and the nearest boot does the rest. Then the next of you looks again.","section":"The United Effort"},{"t":"ue","section":"The United Effort"},{"t":"ueEnd","won":true,"section":"The United Effort"},{"t":"say","text":"The room is yours.\n\nThe scorched corner of the book has fused a dozen leaves into one brittle black wafer. There is time, now, to get them apart whole.","cond":{"on":"ue","won":true},"section":"The United Effort"},{"t":"ueEnd","won":false,"section":"The United Effort"},{"t":"say","text":"You are on the soft stair with the boy before you have decided to go, and what was the room is filling up behind you. The last thing you see in it is lamplight coming through the hole, and patient hands beginning to clear the stone.\n\nAt the lip of the old shaft, in the night air, you count what you came out with. The black book is in three pieces inside somebody''s coat. And Corin is holding something out to you with both hands: a book bound in plain oiled leather. He took it from the niche by the lamp as you carried him past.","cond":{"on":"ue","won":false},"section":"The United Effort"},{"t":"section","title":"The Verse of the Answering","section":"The Verse of the Answering"},{"t":"say","text":"*From the First Book of the Order of the Dark Moon — The Verse of the Answering.*\n\n*Hear how the world nearly ended, and who would not let it.*\n\n*There was a war before this order had a name. It came out of the east like weather, and like weather it hated no one. It only arrived, and kept arriving.*\n\n*Where it passed, the towns burned, and the rivers below them ran grey with ash, and then red. Kings were raised against it and spent, like coin no one expected to see again. Cities older than their own songs went quiet in a single season. Every throne that stood against it fell. Every throne that knelt fell too, only more slowly.*\n\n*At the last there was one kingdom left, and one wall, and one king upon it.*","section":"The Verse of the Answering"},{"t":"match","question":"WHICH OF YOUR FRAGMENTS IS THIS?","quote":"*\"…one wall, and one king upon it.\"*","source":"From the farmhouse on the mill road","section":"The Verse of the Answering","answer":"2-1"},{"t":"act","label":"READ ON","section":"The Verse of the Answering"},{"t":"say","text":"*He had opened his gates to every people the war had driven from their homes, until his city held what was left of the world inside it. His armies were a handful of tired men who still answered to their names — and he knew the name of every man on his wall. His allies were names cut into stone. His own household had packed what little they could carry, for a flight that had nowhere left to go.*\n\n*It is told that he walked that wall every night of the siege; that he did not sleep; that he did not weep where anyone could see. It is told that the enemy''s fires outnumbered the stars. And it is told that on the last evening their herald rode up to the gate and named the hour of the city''s ending — dawn — and that the king heard him out, and thanked him, and sent him home with bread.*\n\n*He had been asked to kneel. He would not.*\n\n*And that night, while the city waited for its last dawn, the moon went dark.*","section":"The Verse of the Answering"},{"t":"act","label":"READ ON","section":"The Verse of the Answering"},{"t":"say","text":"*His house had kept a thing since before his house had a name. No one living could say what it was. It was old; it was not to be sold, or lost, or given away; that was all the keeping had ever passed down. That, and a few pages in a hand no one could read whole — of which, that night, by the light of a single candle, he could read one line:*\n\n**[Set apart on the page, in an older hand — words older than the Order''s own name, and nothing like the plain, careful hand the Seekers left in every fragment]**\n**\"Blood beneath the dark moon — and it answers.\"**\n\n*So the king went down alone into the oldest room of his house, with the moon gone out above him and the enemy''s fires waiting for morning. He set the thing on the stone before him. He opened his palm with his own knife. He had nothing left to lose, and he said so aloud, and he gave it his blood.*\n\n*It answered.*\n\n*And what answered him went out of that room, over the wall, and into the dark where the enemy''s camp lay waiting for dawn.*","section":"The Verse of the Answering"},{"t":"match","question":"WHICH OF YOUR FRAGMENTS IS THIS?","quote":"*\"He opened his palm with his own knife.\"*","source":"From the roots at the shaft''s mouth, the night they drove you back","section":"The Verse of the Answering","answer":"2-4"},{"t":"act","label":"READ ON","section":"The Verse of the Answering"},{"t":"say","text":"*No one who stood on the wall has left us their telling. Ours comes from his own house — from those who watched from the high windows while the city slept, and told it after, and never told it any other way. In the dark, the enemy''s camp rose: every man of it, all at once, the way a field of birds lifts at a single sound. They did not arm. They did not cry out. They walked out past their own fires into the night, and they did not stop. By morning the fires were cold, the tents stood empty, and the horses wandered loose in the fields. No one ever found where the men had gone.*\n\n*The city that had been told to expect its ending climbed onto its walls and looked out on nothing, and wept. It is told that they wept for him that morning, every one of them, for joy. That was the morning of the answering. The war that had eaten the world was broken, and the world, which had been ending, did not end.*\n\n*And the world he saved took back his name. It scraped it from its stones and burned it from its books, and taught its children the story of that war with him cut out of it.*","section":"The Verse of the Answering"},{"t":"say","text":"You know this war. Every child in the land does. *The Grey Host broke at Highwall of a fever in its camp, and Highwall was spared by luck.* That is how you were taught it.\n\nA fever. Luck. No king anywhere in it.\n\nAnd in Meira''s notes, two nights ago, pressed hard into the paper: *\"Not one of these fragments names him. Neither does anything else I can find — every record of him scraped clean. Whoever he was, someone wanted him forgotten.\"*\n\nThe Order says no one who stood on that wall left a telling. Your first fragment begins: *\"We held his last wall the night it was meant to fall.\"*\n\nSomebody did leave one. They hid it in a beam, behind a loose board.","section":"The Verse of the Answering"},{"t":"act","label":"READ ON","section":"The Verse of the Answering"},{"t":"say","text":"*So the faithful remember him, and give the marked blood in his name.*\n\n*Until the throne rise whole.*","section":"The Verse of the Answering"},{"t":"say","text":"*Until the throne rise whole.* It''s what they were chanting over Corin, while the knife was out.","section":"The Verse of the Answering"},{"t":"section","title":"The ledger","section":"The ledger"},{"t":"say","text":"It''s Corin who shows you. Still shaking, he points past the table to a niche in the wall, where a lamp still burns beside another book — nothing like the Order''s scripture. This one is bound in plain oiled leather, the kind a merchant keeps his accounts in.\n\nIt''s a ledger.\n\nPage after page of children''s names. Beside each name, a place. Beside each place, a date, and the miles to the next. The newest pages are in one small, careful hand. The oldest are in other hands, faded almost to nothing. And beside many of the old names, a single word, written the same way every time: *given.*","section":"The ledger"},{"t":"say","text":"*given.*","alone":true,"section":"The ledger"},{"t":"say","text":"The newest page has four names on it. They are the four from the wall in the mine. Two are the children you''ve saved: Tamsin, the girl from Fenmark, and Corin, the boy beside you now. The other two you haven''t found yet.","section":"The ledger"},{"t":"section","title":"The turn","section":"The turn"},{"t":"say","text":"The miller''s wife, at her own door: *\"He knew the night he was born — knew it better than I did.\"*","section":"The turn"},{"t":"say","text":"The sliver from the well at Fenmark: *\"Born when the dark has eaten the moon, marked before the first cry''s through.\"*","section":"The turn"},{"t":"say","text":"And Meira''s page, the one that names all of you. Beside each name she wrote a date: the night each of you was born.","section":"The turn"},{"t":"turn","question":"*What do these nights have in common?*","section":"The turn","nudge":"*Read the well''s sliver again.*","answer":"Every one of them is a night the moon went dark."},{"t":"say","text":"**You''re marked too. Every one of you.**","alone":true,"section":"The turn"},{"t":"section","title":"Ask","section":"Ask"},{"t":"say","text":"**You may ask Garrick.** Each of you, one question.","section":"Ask"},{"t":"ask","rows":[{"questions":["DO YOU KNOW HIS NAME?"],"sealed":false,"note":"","answer":"*\"Malakor.\"* Asked how: *\"My grandmother taught me that name.\"*","group":""},{"questions":["HAVE YOU HEARD OF THIS ORDER?"],"sealed":false,"note":"","answer":"*\"I know the name.\"* Asked how: *\"My family''s been in these hills longer than the roads have.\"*","group":""},{"questions":["DO YOU KNOW WHAT THE THING WAS?"],"sealed":false,"note":"","answer":"*\"I know what that page says.\"*","group":""},{"questions":["WHY DON''T THEY TAKE US? WE''RE MARKED TOO"],"sealed":false,"note":"","answer":"*\"Look at the ledger. Every name in it is a child''s.\"*","group":""}],"section":"Ask"},{"t":"section","title":"The Cliffhanger","section":"The Cliffhanger"},{"t":"say","text":"Garrick reads the ledger over someone''s shoulder, and for the first time since you''ve known him he goes quiet in a different way — slower, more careful, like a man choosing his words.\n\n*\"This hand''s been keeping books like this for years,\"* he says at last. *\"This isn''t new, and it isn''t finished. Two places. Two children.\"*\n\nHe closes the ledger and tucks it inside his coat, the same easy way he keeps everything else.","section":"The Cliffhanger"},{"t":"act","label":"ASK HIM FOR IT","section":"The Cliffhanger"},{"t":"say","text":"He hands it straight over. *\"Here. Read every page.\"*","section":"The Cliffhanger"},{"t":"say","text":"Corin is still watching the place where the ledger went. When he speaks, it''s barely a whisper.\n\n*\"There was a girl down here with me. They took her away, not long before you came.\"* He swallows. *\"She said they told her she was going somewhere warm.\"*","section":"The Cliffhanger"},{"t":"summary","lines":["**UNDER THE MILL HILL** · Gathering 2","{EARNED}","The party: Battle {battle} · the room {ue:held|lost}","You learned: **they are the Order of the Dark Moon, and they pray to a king the world cut out of its own story.** He saved it with his blood on the night the moon went dark. The names on the mine wall were never victims: they are offerings, written down for years, and the word beside them is *given*. Corin reached you alive, and already cut. And you are marked too.","Tomorrow: **a girl who was told she was going somewhere warm**"],"section":"The Cliffhanger"}],"ue":{"success":{"0":["The last leg goes. The hill shuts like a book. The dust takes a long time to settle, and when it has there is no hole, no light, and no sound from the other side at all."],"1":["One frame is holding all of it now. You can see which leg.","The slot is a hand wide. A lamp is pushed up to it from the other side, and an eye."],"2":["Left-hand post, low down. The roof behind it comes down in a long soft rush, and the boots on the far side stop.","You call it, and you are right. Somewhere in the dust, on their side, a man is coughing."],"3":["You see it: not the big prop, the little wedge under it. It goes with one kick, and a cart-load of hill sits down in the tunnel''s mouth.","The cross-piece. It was carrying nothing until the first fall; now it is carrying everything. Out it comes. The lamplight in the hole narrows to a slot."]},"fail":{"0":["The room comes in."],"1":["There is room to stand, and not much more. Everything you have not got in your hands is under stone.","The foot of the stair is going."],"2":["The fall comes your way. When the dust thins, the far end of the room is rubble, and the stone table is the edge of what is left.","A crack runs across the ceiling from the hole to the stair, as quick as a lizard."],"3":["The big prop, the obvious one. It was holding up your side. A slab of the old wall leans out and comes down across the floor, and one of the lamps is under it.","Wrong. The roof over the hole stays where it is. The roof over your heads lets go a barrow-load of stone."]},"between":["Corin has put both hands over his ears.","On the stone table, the lamps the fight kicked over are guttering.","Whoever is coming is not hurrying. They have never needed to."]}}'::jsonb)
on conflict (series_id, season_number, week) do update set data = excluded.data;
